<?php
require __DIR__ . '/../bootstrap.php';$db=tools_db();
$r=$db->query("SELECT o.id office_id,o.office_code,o.office_name,COUNT(*) returned_assigned_active FROM legacy_assets la JOIN offices o ON o.id=la.office_id JOIN returns rt ON rt.legacy_asset_id=la.id AND rt.source_type='legacy' AND rt.status='posted' WHERE o.is_active=1 AND (o.office_code IN ('SPM','SPMU') OR o.office_name LIKE '%Supply and Property Management Unit%' OR o.office_name LIKE '%SPMU%') AND COALESCE(la.accountability_status,'active')='active' AND NOT EXISTS(SELECT 1 FROM asset_transfers at WHERE at.source_type='legacy' AND at.legacy_asset_id=la.id AND at.status='posted' AND at.created_at>rt.created_at) GROUP BY o.id,o.office_code,o.office_name");foreach($r->fetch_all(MYSQLI_ASSOC) as $row)print_r($row);
